\begin{array}{ccc}
\Psi_t = \displaystyle\sum_{t=0}^{\infty} r_t & \Psi_t = \displaystyle\sum_{t'=t}^{\infty} r_{t'} & \Psi_t = \displaystyle\sum_{t'=t}^{\infty} r_{t'} - b(s_t) \\
\text{total reward of the trajectory} & \text{reward following action } a_t & \text{baselined version of previous formula} \\[2em]
\Psi_t = Q^{\pi}(s_t, a_t) & \Psi_t = A^{\pi}(s_t, a_t) & \Psi_t = r_t + V^{\pi}(s_{t+1}) - V^{\pi}(s_t) \\
\text{state-action value function} & \text{advantage function} & \text{TD residual}
\end{array}

\begin{aligned}
& V^{\pi}(s_t) := \mathbb{E}_{\substack{s_{t+1:\infty}, \\ a_{t:\infty}}} \left[ \sum_{l=0}^{\infty} r_{t+l} \right] \qquad Q^{\pi}(s_t, a_t) := \mathbb{E}_{\substack{s_{t+1:\infty}, \\ a_{t+1:\infty}}} \left[ \sum_{l=0}^{\infty} r_{t+l} \right] \quad  \\
& A^{\pi}(s_t, a_t) := Q^{\pi}(s_t, a_t) - V^{\pi}(s_t), \quad \text{(Advantage function)}. 
\end{aligned}

\begin{aligned}
& V^{\pi, \gamma}(s_t) := \mathbb{E}_{\substack{s_{t+1:\infty}, \\ a_{t:\infty}}} \left[ \sum_{l=0}^{\infty} \gamma^l r_{t+l} \right] \qquad \qquad Q^{\pi, \gamma}(s_t, a_t) := \mathbb{E}_{\substack{s_{t+1:\infty}, \\ a_{t+1:\infty}}} \left[ \sum_{l=0}^{\infty} \gamma^l r_{t+l} \right] \\
& A^{\pi, \gamma}(s_t, a_t) := Q^{\pi, \gamma}(s_t, a_t) - V^{\pi, \gamma}(s_t).
\end{aligned}

\begin{aligned}
\hat{A}_t^{\mathrm{MC}}
&=
\sum_{l=0}^{\infty}\gamma^l r_{t+l},
&& \text{Discounted Monte Carlo return, } \gamma\text{-just}; \\[2mm]
\hat{A}_t^{Q}
&=
Q^{\pi,\gamma}(s_t,a_t),
&& \text{Discounted state-action value, } \gamma\text{-just}; \\[2mm]
\hat{A}_t^{A}
&=
A^{\pi,\gamma}(s_t,a_t),
&& \text{Discounted advantage function, } \gamma\text{-just}; \\[2mm]
\hat{A}_t^{\mathrm{TD}}
&=
r_t+\gamma V^{\pi,\gamma}(s_{t+1})-V^{\pi,\gamma}(s_t),
&& \text{One-step TD residual, } \gamma\text{-just}.
\end{aligned}

\begin{aligned}
\mathbb{E}_{s_{t+1}} \left[ \delta_t^{V^{\pi, \gamma}} \right] &= \mathbb{E}_{s_{t+1}} \left[ r_t + \gamma V^{\pi, \gamma}(s_{t+1}) - V^{\pi, \gamma}(s_t) \right] \\
&= \mathbb{E}_{s_{t+1}} \left[ Q^{\pi, \gamma}(s_t, a_t) - V^{\pi, \gamma}(s_t) \right] = A^{\pi, \gamma}(s_t, a_t).
\end{aligned}

\begin{aligned}
\tilde{Q}^{\pi, \gamma}(s, a) &= Q^{\pi, \gamma}(s, a) - \Phi(s) \\
\tilde{V}^{\pi, \gamma}(s, a) &= V^{\pi, \gamma}(s) - \Phi(s) \\
\tilde{A}^{\pi, \gamma}(s, a) &= (Q^{\pi, \gamma}(s, a) - \Phi(s)) - (V^{\pi, \gamma}(s) - \Phi(s)) = A^{\pi, \gamma}(s, a).
\end{aligned}
